window.FILM_WORK_PROMPTS={"work_id":"src-0f35e02019b3515d","records":[{"work_id":"src-0f35e02019b3515d","frame_id":"FG-915823fbfe08a65c","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales007.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"一名深色头发的人物身穿黑色衣物，端坐在白色雕花墙壁前的深色高背椅上。人物面前的白色桌面上放置着一大块鲜红色的不规则物体，背景为大面积的白色装饰墙面。","analysis":"画面采用中心对称构图，人物位于画面正中，仅上半身可见。人物身后的白色墙壁占据背景大部分区域，形成强烈的黑白对比。光线柔和均匀，没有强烈的阴影，使得人物黑色的衣物与背景分离。前景桌面上鲜红色的物体色彩饱和度高，在整体偏冷、偏白的色调中形成视觉焦点。","prompt":"低分辨率画面，一名深色头发的人物身穿黑色长袖衣物，端坐在深色高背椅上，仅上半身可见。人物位于画面正中，背景是带有浮雕装饰的白色墙壁，墙面纹理清晰。人物面前的白色桌面上放置着一大块鲜红色的不规则物体，形状类似肉块或织物堆叠。整体色调以白色和黑色为主，红色物体形成强烈对比。光线均匀柔和，无强烈阴影，画面呈现出一种静止、压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:29:51-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales007.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-6e84093ce7dbe622","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-736682a350e250c1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales020.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"画面主体为一个巨大的、呈浅褐色的圆润物体，形似倒置的蛋或头部，占据画面中心。其表面可见两个深色小点，上方一点较亮，下方一点较暗。物体被置于一个深色圆形边框内，背景昏暗模糊。","analysis":"构图采用中心对称，主体物体几乎填满画面，环境占比极小。视角为平视或微仰，光线从上方或前方投射，在物体表面形成柔和的明暗过渡，高光集中在物体顶部。整体色调为暖褐色与深黑色的对比，光色层次单一，营造出一种封闭、压抑的视觉感受。","prompt":"低分辨率画面，中心是一个巨大的、表面光滑的浅褐色圆润物体，形状类似倒置的蛋或头部，占据绝大部分画面。物体表面有两个明显的深色小点，上方一点较小且亮，下方一点较大且暗。物体被一个深色的圆形边框包围，背景为模糊的深褐色，光线柔和，明暗对比强烈，整体色调温暖而昏暗，营造出一种神秘、封闭的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:30:22-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales020.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-9178b48cd93690dc","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-cdd93d37088a9421","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales033.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"昏暗室内，两名人物相对而立。左侧人物穿着浅色长袖衣物，身体前倾，双手伸向右侧人物。右侧人物赤裸上身，身体微侧，两人距离极近，背景为模糊的暗色墙壁。","analysis":"画面采用平视视角，构图紧凑，主体占据画面中心。左侧人物可见上半身，右侧人物可见躯干及手臂。光线昏暗，主要光源似乎来自左上方，照亮了人物面部和右侧人物的肩膀，形成强烈的明暗对比。整体色调偏冷，以灰黑和暗褐色为主，衣物呈现低饱和度的米色。","prompt":"昏暗的室内场景，两名人物近距离相对。左侧人物身穿米色长袖衣物，身体前倾，双手伸向对方。右侧人物赤裸上身，皮肤在微弱光线下呈现暖色调，身体微侧。背景是模糊的深色墙壁，隐约可见悬挂的衣物或杂物。光线从左侧打入，照亮人物面部和右侧人物的肩膀，其余部分隐没在阴影中。画面色调阴郁，以灰黑和暗褐色为主，具有低分辨率的颗粒感，呈现出一种压抑、紧张的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:30:38-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales033.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-24b3a26785443fe0","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-f29ff46e189ba891","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales046.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"一座巨大的灰白色石砌城堡占据画面右侧，拥有圆柱形塔楼和锯齿状城垛。左侧是修剪整齐的绿色几何花园，一条浅色碎石路从前景延伸至城堡脚下，路面上有一个黑色人影正在行走。","analysis":"画面采用广角视角，城堡体量巨大，占据右半部分空间，左侧花园与道路形成引导线。人物全身可见，位于画面下方中央偏左，相对于庞大的建筑显得极小。光线为自然日光，天空呈现淡蓝色并伴有云层，建筑表面有柔和的明暗过渡，整体色调由石墙的灰白、植被的深绿和天空的淡蓝构成。","prompt":"一座宏伟的灰白色石砌城堡矗立在画面右侧，拥有高大的圆柱形塔楼和锯齿状城垛，墙面分布着细长的窗户。左侧是修剪整齐的绿色几何图案花园，一条浅色碎石路从前景延伸至城堡脚下。路面上有一个身穿深色衣物的人影正在行走，人物全身可见，相对于庞大的建筑显得极小。天空呈现淡蓝色，飘浮着白云，自然光照射在建筑表面形成柔和的明暗层次，整体色调由石墙的灰白、植被的深绿和天空的淡蓝构成，呈现出开阔的庄园环境。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:31:03-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales046.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-2e9ade21f0e99a81","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-4356c524268b22de","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales059.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"昏暗狭窄的石壁峡谷中，一名长发人物位于中央通道，身体前倾呈奔跑或快速移动姿态，上方开口处可见绿色植被。","analysis":"构图采用中心对称，两侧高耸粗糙的石壁形成强烈透视引导线，将视线汇聚于中央人物。人物全身可见，在巨大的环境衬托下显得渺小。画面整体极暗，仅顶部开口处有自然光射入，照亮部分植被和人物轮廓，形成强烈的明暗对比，色调以深褐与暗绿为主。","prompt":"低分辨率画面，展示一条幽深狭窄的峡谷通道，两侧是粗糙高耸的深色石壁，纹理模糊。画面中央一名长发人物全身可见，身着浅色衣物，身体前倾，呈现奔跑或快速移动的大姿态。峡谷顶部中央有一个不规则开口，透入自然光，照亮了上方的绿色植被和人物头部区域。整体环境昏暗压抑，明暗对比强烈，光线集中在顶部开口和人物身上，周围石壁隐没在阴影中，营造出神秘且封闭的空间感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T06:31:10-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales059.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-d4c317bfaf22f639","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-b9304497a75e1830","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales008.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"画面主体为一座横跨平静水面的石拱桥，背景是层叠的深色山峦与弥漫的雾气，整体环境占据绝大部分画面，色调阴郁。","analysis":"构图上，石拱桥位于画面中下部，呈水平延伸，其倒影清晰映在下方平静的水面上。背景是层层叠叠的山脉，由近及远逐渐隐没在灰白色的雾气中。光线昏暗，整体呈现冷色调，前景山体与桥身处于阴影中，远处山峦则被雾气笼罩，明暗对比强烈，营造出一种静谧而压抑的氛围。","prompt":"这是一张低分辨率的宽幅画面，主体是一座横跨在平静水面上的石拱桥。桥身呈深褐色，拥有多个拱形结构，其倒影清晰地映在下方如镜的水面上。背景是层叠起伏的山峦，山体覆盖着深色的植被，远处的山峰逐渐隐没在灰白色的浓雾之中。整体光线昏暗，色调偏冷，前景的山坡和桥身处于阴影中，与远处明亮的雾气形成对比，营造出一种静谧、阴郁且带有神秘感的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T15:53:05+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales008.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-48259d3f90b0bca2","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-00b1399939317c94","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales021.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"米黄色石墙中央嵌有白色石框的哥特式双拱窗，窗内可见两名人物头部及肩部，左侧人物着浅色衣物，右侧人物着深色衣物，背景为粗糙石质墙面。","analysis":"构图以石窗为绝对中心，占据画面约三分之一宽度。人物仅露出头部至肩部，被窗框分割为左右两部分，相对窗户比例较小。视角为平视，光线均匀柔和，无明显阴影。色彩以米黄、灰白为主，窗内深色背景与人物浅色衣物形成对比，整体色调古朴沉稳。","prompt":"低分辨率画面，米黄色粗糙石墙占据大部分背景，墙面有零星深色斑点。画面正中是一个白色石质哥特式双拱窗，窗顶有黑色四叶草形装饰。窗内背景深黑，左右各有一名人物仅露出头部和肩部。左侧人物头发灰白，身着浅褐色衣物；右侧人物头发深色，身着深蓝色衣物。两人均面向前方，姿态静止。光线平淡均匀，无强烈明暗对比，整体呈现古朴、静谧的视觉质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T15:53:11+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales021.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-d6040703abde6953","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-75de77e6dca246ff","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales034.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"昏暗室内，一名长发男子坐于床榻边，手持烛台照亮面部，身前躺着被红色织物覆盖的人形轮廓，左侧可见深色床头框架。","analysis":"画面采用低调照明，大面积黑色背景占据主导。男子位于中上部，仅上半身可见，面部被烛光局部照亮，形成强烈明暗对比。前景下方为模糊的红色与肤色色块，暗示躺卧姿态。左侧深色弧形结构作为前景框架，增强了空间纵深感。整体色调偏冷暗，仅烛光区域呈现暖黄。","prompt":"昏暗室内场景，一名长发男子坐于床榻边，仅上半身可见，面部被烛光局部照亮，神情凝重。他手持烛台，暖黄光晕在黑暗中形成唯一亮区。身前下方躺着被红色织物覆盖的人形轮廓，模糊不清。左侧前景有深色床头框架，呈弧形遮挡部分视野。背景几乎全黑，仅能辨识微弱的环境轮廓。整体色调深沉，明暗对比强烈，红色织物在暗处呈现暗红色块，烛光在男子面部和手部形成局部高光。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T15:53:17+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales034.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-2ab84d87d9094082","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-73363782b62d8d60","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales047.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"昏暗森林中，一名人物站立于画面右侧，手持一根长杆，杆端有明亮的橙黄色亮区，背景为深绿色树木剪影。","analysis":"人物位于画面右侧三分之一处，呈站立姿态，身体上半身可见，下半身隐没在黑暗中。人物面部朝向镜头方向，轮廓在暗部中依稀可辨。左侧长杆斜向延伸，杆端的亮区是画面主要光源，照亮了人物部分面部和肩部。背景树木呈深绿色块状分布，整体明暗对比强烈，亮区与暗部形成鲜明反差。","prompt":"昏暗森林夜景，一名人物站立于画面右侧，身穿深色衣物，身体上半身可见，面部轮廓在暗处依稀可辨。人物手持一根长杆向左下方斜向延伸，杆端有明亮的橙黄色亮区，呈不规则形状，是画面主要光源，照亮人物部分面部和肩部。背景为深绿色树木剪影，树影模糊，整体环境昏暗，明暗对比强烈，亮区与周围暗部形成鲜明反差，画面色调偏冷暗，仅亮区呈暖色。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T15:53:23+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales047.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-7c5428f21b599f26","origin":"visual"},{"work_id":"src-0f35e02019b3515d","frame_id":"FG-9a9531ff7b3be835","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales060.jpg","source_page":"https://film-grab.com/2017/03/31/tale-of-tales/","scene":"昏暗的岩石洞穴内，一名长发女子仰头面对右侧俯身靠近的深色毛发人物，背景为粗糙的岩壁，整体氛围压抑。","analysis":"画面采用对角线构图，人物占据画面右侧及下方主要区域。右侧人物仅可见背部及头部轮廓，体型在画面中显得庞大，呈俯视姿态；左侧女子可见头部及肩部，面部朝向右上方。环境光线极暗，仅人物面部及发丝有微弱冷色反光，背景岩壁隐没在阴影中，明暗对比强烈，色调偏冷绿。","prompt":"昏暗的岩石洞穴环境，低分辨率画面。右侧前景是一个巨大的深色毛发人物背影，头部低垂，面部带有模糊的红色痕迹，正俯身向下。左侧下方是一名长发女子，可见头部和肩部，身穿浅色衣物，面部朝向右侧上方，神情凝重。背景是粗糙的深色岩壁，布满苔藓或阴影。整体光线微弱，色调偏冷绿，明暗对比强烈，营造出压抑、紧张的对峙氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T15:53:29+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/taleoftales060.jpg","observed_dimensions":[500,213],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-b84e10578bccd668","origin":"visual"}]};